import "dotenv/config";
import { randomUUID } from "node:crypto";
import { db } from "./client.js";

/**
 * Development-only seed for supplier records.
 *
 * All names and contact details below are fictional and intended for local
 * development and testing only. Do not run this against a production database.
 * Re-running is idempotent: existing suppliers are matched by email and
 * updated in place (preserving their database-generated IDs and any
 * booking_services relationships); new suppliers are inserted.
 *
 * Supplier IDs are generated by the application (randomUUID), not hardcoded,
 * and preserved across re-seeds.
 */

const suppliers = [
  { name: "SnapMagic Booth", category: "Photo Booth", contact_number: "09171234501", email: "snapmagic@example.com" },
  { name: "FlashFrame Studio", category: "Photography and Videography", contact_number: "09171234502", email: "flashframe@example.com" },
  { name: "PowerBeat Events", category: "Sounds and Lights", contact_number: "09171234503", email: "powerbeat@example.com" },
  { name: "GlowStage Productions", category: "Sounds and Lights", contact_number: "09171234504", email: "glowstage@example.com" },
  { name: "Happy Cups Cart", category: "Food Carts and Beverage Stations", contact_number: "09171234505", email: "happycups@example.com" },
  { name: "Sweet Wheels", category: "Dessert and Food Carts", contact_number: "09171234506", email: "sweetwheels@example.com" },
  { name: "Bloom and Bliss Styling", category: "Decorations and Event Styling", contact_number: "09171234507", email: "bloombliss@example.com" },
  { name: "Elegant Spaces Rental", category: "Tables, Chairs, and Tents", contact_number: "09171234508", email: "elegantspaces@example.com" },
  { name: "Spotlight Entertainment", category: "Hosts and Performers", contact_number: "09171234509", email: "spotlight@example.com" },
  { name: "Royal Ride Logistics", category: "Event Transportation", contact_number: "09171234510", email: "royalride@example.com" },
];

try {
  const result = await db.transaction().execute(async (trx) => {
    const rows: { id: string; name: string; category: string; email: string }[] = [];
    for (const supplier of suppliers) {
      const existing = await trx
        .selectFrom("suppliers")
        .select("id")
        .where("email", "=", supplier.email)
        .executeTakeFirst();

      if (existing) {
        await trx
          .updateTable("suppliers")
          .set({
            name: supplier.name,
            category: supplier.category,
            contact_number: supplier.contact_number,
            updated_at: new Date(),
          })
          .where("id", "=", existing.id)
          .execute();
        rows.push({ id: existing.id, name: supplier.name, category: supplier.category, email: supplier.email });
      } else {
        const id = randomUUID();
        await trx
          .insertInto("suppliers")
          .values({
            id,
            name: supplier.name,
            category: supplier.category,
            contact_number: supplier.contact_number,
            email: supplier.email,
            is_internal: false,
          })
          .execute();
        rows.push({ id, name: supplier.name, category: supplier.category, email: supplier.email });
      }
    }
    return rows;
  });

  console.table(result.map(({ name, category, email }) => ({ name, category, email })));
  console.log(`Seeded ${result.length} supplier records (development only).`);
} finally {
  await db.destroy();
}
